const podcastData = $('Get Podcast Trends').first().json;
const newsData = $json;
const podcastEntities = podcastData.entities || [];
const newsEntities = newsData.entities || [];

const newsSet = new Map(newsEntities.map(e => [e.entity_text.toLowerCase(), e]));
const overlap = [];
for (const pe of podcastEntities) {
  const match = newsSet.get(pe.entity_text.toLowerCase());
  if (match) overlap.push({ entity: pe.entity_text, type: pe.entity_type,
    podcast_mentions: pe.total_mentions, news_mentions: match.total_mentions });
}

const podcastList = podcastEntities.slice(0, 15).map(e => `${e.entity_text} (${e.entity_type}, ${e.total_mentions}x across ${e.episode_count} episodes)`).join('; ');
const newsList = newsEntities.slice(0, 15).map(e => `${e.entity_text} (${e.entity_type}, ${e.total_mentions}x across ${e.article_count} articles)`).join('; ');
const overlapList = overlap.length
  ? overlap.map(o => `${o.entity} (podcasts: ${o.podcast_mentions}x, news: ${o.news_mentions}x)`).join('; ')
  : 'none this week';

const prompt = `You are a cross-medium trends analyst for a personal podcast+news system. `
  + `Here is this week's top entities/topics from podcast transcripts: ${podcastList}. `
  + `Here is this week's top entities/topics from the news corpus: ${newsList}. `
  + `Entities appearing in BOTH: ${overlapList}. `
  + `Write a short (100-150 word) narrative: what's resonating across both the user's podcast `
  + `listening and the broader news this week, calling out the overlap specifically as the most `
  + `interesting signal (something showing up in both independently-curated streams). Be specific, `
  + `not generic. Respond with ONLY the narrative, no preamble.`;

return [{ json: { prompt, overlap_count: overlap.length, podcast_count: podcastEntities.length, news_count: newsEntities.length } }];

const overlapCount = $('Compute Overlap + Build Prompt').first().json.overlap_count;
const narrative = ($json.response || 'No trends narrative available this week.').trim();
const dateLabel = $now.toFormat('yyyy-MM-dd');
const text = `\ud83d\udcca Cross-Medium Trends \u2014 ${dateLabel}\n\n${narrative}\n\n`
  + `_${overlapCount} entities showed up in both podcasts and news this week \u2014 posted by podcast-bot_`;
const matrixPayload = JSON.stringify({ msgtype: 'm.text', body: text });
return [{ json: { txn_id: 'trends-' + Date.now(), matrixPayload } }];
